// Keep the animation's display-sized CSS viewport while the native macOS window
// contains only the pet and its visible panels. Native input is translated by the
// WebContentsView, so dragging and the sandbox keep their original coordinates.
const { BaseWindow, WebContentsView } = require('electron');

const MARGIN = 16;
const SHRINK_DELAY_MS = 250;

function contentBounds(rect, scene) {
  if (!rect || ![rect.x, rect.y, rect.width, rect.height].every(Number.isFinite)
    || rect.width <= 0 || rect.height <= 0) return null;
  const x = Math.max(0, Math.floor(rect.x - MARGIN));
  const y = Math.max(0, Math.floor(rect.y - MARGIN));
  const right = Math.min(scene.width, Math.ceil(rect.x + rect.width + MARGIN));
  const bottom = Math.min(scene.height, Math.ceil(rect.y + rect.height + MARGIN));
  return right > x && bottom > y ? { x, y, width: right - x, height: bottom - y } : null;
}

class ContentWindow extends BaseWindow {
  constructor({ webPreferences, x, y, width, height, ...options }) {
    super({ ...options, x, y, width: 1, height: 1 });
    this.scene = { x, y, width, height };
    this.crop = null;
    this.shrinkAt = 0;
    this.view = new WebContentsView({ webPreferences });
    this.view.setBackgroundColor('#00000000');
    this.contentView.addChildView(this.view);
    this.view.setBounds({ x: 0, y: 0, width, height });
    // BaseWindow does not own the lifecycle of a WebContentsView.
    this.once('closed', () => { if (!this.webContents.isDestroyed()) this.webContents.close(); });
  }

  get webContents() { return this.view.webContents; }
  loadURL(url) { return this.webContents.loadURL(url); }
  getSceneBounds() { return { ...this.scene }; }

  setSceneBounds(scene) {
    this.scene = { ...scene };
    const crop = this.crop ?? { x: 0, y: 0, width: 1, height: 1 };
    this.crop = null;
    this.fitContent({ ...crop, x: Math.min(crop.x, scene.width - 1), y: Math.min(crop.y, scene.height - 1) }, true);
  }

  fitContent(rect, force = false) {
    const next = contentBounds(rect, this.scene);
    if (!next) return;
    const old = this.crop;
    if (!force && old) {
      // Breathing/emotes must not resize a native window on every animation tick.
      const contains = rect.x >= old.x && rect.y >= old.y
        && rect.x + rect.width <= old.x + old.width && rect.y + rect.height <= old.y + old.height;
      const smaller = old.width - next.width > MARGIN * 2 || old.height - next.height > MARGIN * 2;
      if (contains && !smaller) { this.shrinkAt = 0; return; }
      if (contains) {
        if (!this.shrinkAt) this.shrinkAt = Date.now() + SHRINK_DELAY_MS;
        if (Date.now() < this.shrinkAt) return;
      }
    }
    this.shrinkAt = 0;
    this.crop = next;
    this.view.setBounds({ x: -next.x, y: -next.y, width: this.scene.width, height: this.scene.height });
    this.setBounds({ x: this.scene.x + next.x, y: this.scene.y + next.y, width: next.width, height: next.height });
  }
}

module.exports = { ContentWindow, contentBounds };
